entries[24661] = { ["name"] = "Ruhelose Stärke", ["text"] = "Sofort\nErhöht 20 Sek. lang Euren Nahkampf- und Distanzschadensbonus um 40 Punkte. Jedesmal, wenn Ihr ein Ziel trefft, wird dieser Bonus um 2 Punkte reduziert." }
