entries[24664] = { ["name"] = "Schlaf", ["text"] = "Unbegrenzte Reichweite\nSofort\nVersetzt in der Nähe befindliche Feinde bis zu 6 Sek. lang in Schlaf. Jeglicher erlittene Schaden führt dazu, dass sie aufwachen." }
entries[24666] = { ["name"] = "Frostschaden erhöhen 132", ["text"] = "Erhöht durch Frostzauber und Frosteffekte zugefügten Schaden um bis zu 132." }
entries[24667] = { ["name"] = "Frostschaden erhöhen 72", ["text"] = "Erhöht durch Frostzauber und Frosteffekte zugefügten Schaden um bis zu 72." }
entries[24668] = { ["name"] = "Schattenblitz", ["text"] = "250 Mana 40 Meter Reichweite\nWirken in 2 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Feind und verursacht Schattenschaden." }
entries[24669] = { ["name"] = "Feuerregen", ["text"] = "250 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nLässt einen Schmelzregen niedergehen, der alle Feinde im ausgewählten Gebiet verbrennt und ihnen 10 Sek. lang alle 2 Sek. 500 Feuerschaden zufügt." }
entries[24670] = { ["name"] = "Inferno", ["text"] = "350 Mana 100 Meter Reichweite\nWirken in 3 sek.\nReagenzien:\nHöllenstein\nBeschwört einen Meteor aus dem Wirbelnden Nether, der 200 Feuerschaden verursacht und alle gegnerischen Ziele im Gebiet 2 Sek. lang betäubt. Aus dem Krater erhebt sich eine Höllenbestie, die 5 Min. lang unter dem Befehl des Zaubernden steht. Sobald die Kontrolle verloren ist, muss die Höllenbestie unterworfen werden, um sie unter Kontrolle zu halten. Kann nur draußen verwendet werden." }
entries[24671] = { ["name"] = "Schnapptritt", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nFügt einem Feind 875 bis 1125 Schaden zu und betäubt ihn 2 Sek. lang." }
entries[24672] = { ["name"] = "Unheilige Raserei", ["text"] = "200 Mana 30 Meter Reichweite\nSofort\nErhöht das Angriffstempo eines Verbündeten 20 Sek. lang um 50%, fügt diesem Verbündeten aber auch alle 2 Sek. 200 Naturschaden zu." }
entries[24673] = { ["name"] = "Blutfluch", ["text"] = "20 Meter Reichweite\nSofort\nErhöht den erlittenen körperlichen Schaden eines Feindes 10 Min. lang um 500." }
entries[24674] = { ["name"] = "Schleier des Schattens", ["text"] = "20 Meter Reichweite\nSofort\nVerringert 10 Sek. lang die Heileffekte eines Feindes um 75%." }
