entries[24687] = { ["name"] = "Aspekt von Jeklik", ["text"] = "Sofort\nFügt in der Nähe befindlichen Feinden normalen Schaden plus 1313 bis 1687 zu und hindert sie 5 Sek. lang am Wirken von Zaubern." }
entries[24688] = { ["name"] = "Aspekt von Venoxis", ["text"] = "30 Meter Reichweite\nSofort\nSpuckt Gift auf in der Nähe befindliche Feinde; fügt ihnen erst Naturschaden und dann 10 Sek. lang alle 2 Sek. zusätzlichen Schaden zu." }
