entries[25318] = { ["name"] = "Ring des Zwielichts", ["text"] = "Wirken in 12.5 sek.\nTools: Juweliersset\nReagenzien:\nSchattenedelstein (2), Bronzebarren (2)\nRing des Zwielichts\nWird beim Anlegen gebunden\nEinzigartig anlegbarFinger\n+4 Ausdauer\n+4 Intelligenz\n23" }
entries[25320] = { ["name"] = "Schwere goldene Halskette des Kampfes", ["text"] = "Wirken in 12.5 sek.\nTools: Juweliersset\nReagenzien:\nGoldbarren , Moosachat (2), Elixier der Ogerstärke\nSchwere goldene Halskette des Kampfes\nWird beim Anlegen gebunden\nHals\n+5 Stärke\n+5 Ausdauer\n30\nBenutzen: Gewährt nahen Gruppenmitgliedern 30 Min. lang 10 zusätzliche Stärke.\n10 Aufladungen" }
entries[25321] = { ["name"] = "Krone der Mondseele", ["text"] = "Wirken in 12.5 sek.\nTools: Juweliersset\nReagenzien:\nGeringer Mondstein (3), Kleine irisierende Perle (3), Seelenstaub (4), Silberbarren (4), Manatrank (2)\nKrone der Mondseele\nWird beim Anlegen gebunden\nKopf Stoff\n39 Rüstung\n+6 Intelligenz\nHaltbarkeit 50 / 50\n26\nAnlegen: Stellt alle 5 Sek. 6 Mana wieder her." }
entries[25322] = { ["name"] = "Weitreichendes Zerschmettern", ["text"] = "Sofort\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden normalen Schaden plus 1750 bis 2250 zu und stößt sie zurück." }
entries[25323] = { ["name"] = "Tückischer Mondsteinring", ["text"] = "Wirken in 12.5 sek.\nTools: Juweliersset\nReagenzien:\nGeringer Mondstein , Schattenöl , Eisenbarren (4)\nTückischer Mondsteinring\nWird beim Anlegen gebunden\nEinzigartig anlegbarFinger\n+5 Intelligenz\n27\nAnlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 6." }
entries[25329] = { ["name"] = "Heilige Nova" }
entries[25331] = { ["name"] = "Heilige Nova", ["text"] = "875 Mana\nSofort\nVerursacht eine Explosion heiligen Lichts um den Zaubernden herum und fügt allen Zielen in einem Umkreis von 10 Metern 244 bis 283 Heiligschaden zu. Zusätzlich werden alle Gruppenmitglieder in einem Umkreis von 10 Metern um 386 bis 448 geheilt. Dieser Effekt erzeugt keine Bedrohung." }
entries[25339] = { ["name"] = "Amulett des Mondes", ["text"] = "Wirken in 12.5 sek.\nTools: Juweliersset\nReagenzien:\nGeringer Mondstein (2), Bronzefassung\nAmulett des Mondes\nWird beim Anlegen gebunden\nHals\n+4 Intelligenz\n+4 Willenskraft\n25\nBenutzen: Gewährt nahen Gruppenmitgliedern 30 Min. lang 10 zusätzliche Willenskraft.\n10 Aufladungen" }
