entries[25346] = { ["name"] = "Arkane Geschosse", ["text"] = "30 Meter Reichweite\nSofort\nSchleudert ein arkanes Geschoss auf den Feind und verursacht 234 Arkanschaden." }
entries[25347] = { ["name"] = "Tödliches Gift V", ["text"] = "Wirken in 3 sek.\nReagenzien:\nTodeskraut (2), Kristallphiole\nÜberzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner 12 Sek. lang zu vergiften und ihm 136 Naturschaden zuzufügen. Kann bis zu 5-mal auf ein einzelnes Ziel angewendet werden." }
