entries[25351] = { ["name"] = "Tödliches Gift V", ["text"] = "Wirken in 3 sek.\nBenötigt Nahkampfwaffe\nÜberzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner 12 Sek. lang zu vergiften und ihm 136 Naturschaden zuzufügen. Kann bis zu 5-mal auf ein einzelnes Ziel angewendet werden.\n(Procchance: 30%)" }
