entries[25384] = { ["name"] = "Heiliges Feuer", ["text"] = "290 Mana 30 Meter Reichweite\nWirken in 3.5 sek.\nVerzehrt den Feind in heiligen Flammen, die 426 bis 537 Heiligschaden sowie zusätzlich 10 Sek. lang insgesamt 165 Heiligschaden verursachen." }
entries[25387] = { ["name"] = "Gedankenschinden", ["text"] = "230 Mana 20 Meter Reichweite\nKanalisiert (Wirken in 3 sek.)\nGreift die Gedanken des Ziels mit Schattenenergie an, verursacht 3 Sek. lang 528 Schattenschaden und verringert das Bewegungstempo des Ziels um 50%." }
