entries[25422] = { ["name"] = "Kettenheilung", ["text"] = "435 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt das befreundete Ziel um 624 bis 710 und springt dann weiter, um weitere in der Nähe befindliche Ziele zu heilen. Wenn es auf ein Gruppenmitglied gewirkt wird, springt die Heilung nur auf andere Gruppenmitglieder über. Jeder Sprung verringert die Effektivität des Heilens um 50%. Heilt 3 Ziele insgesamt." }
entries[25423] = { ["name"] = "Kettenheilung", ["text"] = "540 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt das befreundete Ziel um 833 bis 950 und springt dann weiter, um weitere in der Nähe befindliche Ziele zu heilen. Wenn es auf ein Gruppenmitglied gewirkt wird, springt die Heilung nur auf andere Gruppenmitglieder über. Jeder Sprung verringert die Effektivität des Heilens um 50%. Heilt 3 Ziele insgesamt." }
entries[25424] = { ["name"] = "Giftblitz", ["text"] = "45 Meter Reichweite\nWirken in 2 sek.\nSchießt Gift auf den Feind, fügt ihm Naturschaden und dann 10 Sek. lang alle 1 Sek. zusätzlichen Schaden zu." }
entries[25425] = { ["name"] = "Schockwelle", ["text"] = "Sofort\nVerursacht 1313 bis 1687 Naturschaden bei in der Nähe befindlichen Feinden und verringert ihr Angriffstempo um 0% und Bewegungstempo auf 1% des Grundwertes. Hält 2 Sek. lang an." }
entries[25429] = { ["name"] = "Verblassen", ["text"] = "330 Mana\nSofort 30 sek. Abklingzeit" }
entries[25431] = { ["name"] = "Inneres Feuer", ["text"] = "375 Mana\nSofort\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seine Rüstung um 1580 erhöht. Ein erlittener Nahkampf- oder Distanzangriffstreffer verbraucht eine Aufladung. Hält 10 Min. lang an oder bis alle 20 Aufladungen verbraucht sind." }
entries[25433] = { ["name"] = "Schattenschutz", ["text"] = "810 Mana 30 Meter Reichweite\nSofort\nErhöht 10 Min. lang die Widerstandskraft des Ziels gegen alle Schattenzauber um 70." }
entries[25435] = { ["name"] = "Auferstehung", ["text"] = "60% von Grundmana 30 Meter Reichweite\nWirken in 10 sek.\nBringt einen Spieler mit 1100 Gesundheit und 1150 Mana ins Leben zurück. Kann nicht während des Kampfes verwendet werden." }
entries[25437] = { ["name"] = "Verzweifeltes Gebet", ["text"] = "Sofort 10 min Abklingzeit\nHeilt den Zaubernden sofort um 1637 bis 1924." }
entries[25439] = { ["name"] = "Kettenblitzschlag", ["text"] = "650 Mana 30 Meter Reichweite\nWirken in 2 sek. 6 sek. Abklingzeit\nSchleudert einen Blitzschlag auf den Feind, der 620 bis 705 Naturschaden verursacht und zu in der Nähe befindlichen Feinden weiterspringt. Jeder Sprung verringert den Schaden um 30%. Wirkt auf insgesamt 3 Ziele." }
entries[25440] = { ["name"] = "Rückkopplung" }
entries[25441] = { ["name"] = "Rückkopplung", ["text"] = "705 Mana\nSofort 3 min Abklingzeit\nIhr werdet 15 Sek. lang in ein Feld aus Antimagie gehüllt. Jeder erfolgreich auf den Priester gewirkte Zauber entzieht dem Angreifer 165 Mana. Für jeden auf diese Weise entzogenen Manapunkt erleidet das Ziel 1 Punkt Schattenschaden." }
entries[25442] = { ["name"] = "Kettenblitzschlag", ["text"] = "760 Mana 30 Meter Reichweite\nWirken in 2 sek. 6 sek. Abklingzeit\nSchleudert einen Blitzschlag auf den Feind, der 734 bis 838 Naturschaden verursacht und zu in der Nähe befindlichen Feinden weiterspringt. Jeder Sprung verringert den Schaden um 30%. Wirkt auf insgesamt 3 Ziele." }
entries[25446] = { ["name"] = "Sternensplitter", ["text"] = "30 Meter Reichweite\nSofort 30 sek. Abklingzeit\nLässt Sternensplitter auf den Kopf des feindlichen Ziels regnen und verursacht 15 Sek. lang 785 Arkanschaden." }
entries[25448] = { ["name"] = "Blitzschlag", ["text"] = "275 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Blitz auf das Ziel und fügt ihm 505 bis 576 Naturschaden zu." }
entries[25449] = { ["name"] = "Blitzschlag", ["text"] = "300 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Blitz auf das Ziel und fügt ihm 571 bis 652 Naturschaden zu." }
entries[25454] = { ["name"] = "Erdschock", ["text"] = "535 Mana 20 Meter Reichweite\nSofort 6 sek. Abklingzeit\nSchockt das Ziel unmittelbar mit erschütternder Kraft und verursacht 661 bis 696 Naturschaden. Unterbricht außerdem das Wirken von Zaubern und verhindert 2 Sek. lang, dass diese Art Zauber gewirkt werden kann." }
entries[25457] = { ["name"] = "Flammenschock", ["text"] = "500 Mana 20 Meter Reichweite\nSofort 6 sek. Abklingzeit\nVersengt das Ziel sofort mit Feuer und verursacht unmittelbar 377 Feuerschaden sowie 12 Sek. lang 420 Feuerschaden." }
entries[25460] = { ["name"] = "Berührung der Schwäche" }
entries[25461] = { ["name"] = "Berührung der Schwäche", ["text"] = "235 Mana\nSofort\nDer nächste Nahkampfangriff gegen den Zaubernden verursacht 80 Schattenschaden und verringert den vom Angreifer zugefügten Schaden 2 Min. lang um 35." }
entries[25462] = { ["name"] = "Vergrößern" }
entries[25464] = { ["name"] = "Frostschock", ["text"] = "525 Mana 20 Meter Reichweite\nSofort 6 sek. Abklingzeit\nSchockt das Ziel unmittelbar mit Frost, verursacht 647 bis 683 Frostschaden und reduziert das Bewegungstempo um 50%. Hält 8 Sek. lang an. Verursacht ein hohes Maß an Bedrohung." }
entries[25465] = { ["name"] = "Feuerwerk", ["text"] = "30 Meter Reichweite\nWirken in 0.5 sek.\nSchießt einen Feuerwerkskörper auf ein Ziel ab." }
entries[25467] = { ["name"] = "Verschlingende Seuche", ["text"] = "1145 Mana 30 Meter Reichweite\nSofort 3 min Abklingzeit\nInfiziert das Ziel mit einer Krankheit und fügt so 24 Sek. lang 1216 Schattenschaden zu. Schaden, der durch 'Verschlingende Seuche' zugefügt wird, heilt den Zaubernden." }
entries[25469] = { ["name"] = "Blitzschlagschild", ["text"] = "325 Mana\nSofort\nDer Zaubernde ist von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Fernkampf- oder Zauberangriff getroffen wird, erleidet der Angreifende 232 Naturschaden. Dies kostet einen Kugelblitz. Es wird immer nur ein einzelner Kugelblitz alle paar Sekunden abgefeuert. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)" }
entries[25470] = { ["name"] = "Verhexung der Schwäche", ["text"] = "295 Mana 30 Meter Reichweite\nSofort\nSchwächt das feindliche Ziel und verringert den verursachten Schaden um 35 sowie die Wirksamkeit jeglicher Heilung um 20%. Hält 2 Min. lang an." }
entries[25471] = { ["name"] = "Angriffsreihenfolge" }
entries[25472] = { ["name"] = "Blitzschlagschild", ["text"] = "400 Mana\nSofort\nDer Zaubernde ist von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Fernkampf- oder Zauberangriff getroffen wird, erleidet der Angreifende 287 Naturschaden. Dies kostet einen Kugelblitz. Es wird immer nur ein einzelner Kugelblitz alle paar Sekunden abgefeuert. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)" }
entries[25477] = { ["name"] = "Schattenschild", ["text"] = "270 Mana\nSofort\nDer Zaubernde ist von Schatten umgeben. Wenn der Zaubernde von einem Nahkampf- oder Distanzangreifer angegriffen wird, wird der Angreifende getroffen und erleidet 130 Schattenschaden. Angreifern kann nur ein Mal alle paar Sekunden Schaden zugefügt werden. So zugefügter Schaden erzeugt keine Bedrohung. 3 Aufladungen. Hält 10 Min. lang an.\n(3.5s Abklingzeit)" }
entries[25479] = { ["name"] = "Waffe des Felsbeißers", ["text"] = "170 Mana\nSofort\nDie Waffe des Schamanen mit Magie erfüllen. Erhöht den pro Sekunde verursachten Schaden der Waffe um 49. Hält 30 Minuten lang an." }
