entries[25498] = { ["name"] = "Barbarischer Eisenhalsschmuck", ["text"] = "Wirken in 12.5 sek.\nTools: Juweliersset\nReagenzien:\nEisenbarren (8), Großer Fangzahn (2), Bronzefassung (2)\nBarbarischer Eisenhalsschmuck\nWird beim Anlegen gebunden\nHals\n25\nAnlegen: Erhöht die Angriffskraft um 10." }
