entries[25895] = { ["name"] = "Großer Segen der Rettung", ["text"] = "13% von Grundmana 40 Meter Reichweite\nSofort\nReagenzien:\nSymbol der Könige\nBelegt alle Mitglieder einer Gruppe oder eines Schlachtzuges, die dieselbe Klasse wie das Ziel haben, mit dem großen Segen der Rettung. Der große Segen der Rettung reduziert die Bedrohung, die das Ziel erzeugt, 30 Min. lang um 30%. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
